def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    parts = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        abs_coeff = abs(coeff)

        if deg == 0:
            coeff_part = str(coeff)
        else:
            coeff_part = '' if abs_coeff == 1 else str(abs_coeff)

        if deg == 0:
            var_part = ''
        elif deg == 1:
            var_part = 'x'
        else:
            var_part = f'x^{deg}'

        term = coeff_part + var_part

        if not parts:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        parts.append(sign + term)

    return ''.join(parts) if parts else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: encoded and original must be of same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    # Build mapping from encoded to original
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # Contradiction
        else:
            mapping[e_char] = o_char

    # Check that all 26 uppercase letters are represented as keys
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for c in message:
        if c not in mapping:
            return "Failed"  # Unknown character
        decoded_chars.append(mapping[c])

    return "".join(decoded_chars)

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.

    Parameters:
    n (int): The integer to be partitioned.
    k (int): The number of parts to divide n into.
    x (int): The minimum value for each part.

    Returns:
    int: The number of distinct partitioning ways.
    """
    if k <= 0:
        return 0
    # After subtracting the minimum value from each part,
    # we need to partition the remaining amount into k nonnegative parts.
    remaining = n - k * x
    if remaining < 0:
        return 0

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def part(amount: int, max_part: int) -> int:
        """
        Number of partitions of 'amount' using parts of size at most 'max_part'.
        This is equal to the number of partitions of 'amount' into at most 'max_part'
        parts, which by conjugation is the same as partitions into at most 'max_part' parts.
        """
        if amount == 0:
            return 1  # exactly one way to partition zero (the empty partition)
        if max_part == 0 or amount < 0:
            return 0
        if max_part > amount:
            max_part = amount
        # Either we do not use a part of size 'max_part' or we use at least one.
        return part(amount, max_part - 1) + part(amount - max_part, max_part)

    return part(remaining, k)

def string_transformation(A: str, B: str, rules: list) -> "Union[int, str]":
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps; returns minimal steps or "NO ANSWER!" if impossible.
    """
    from collections import deque

    if A == B:
        return 0

    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, steps = queue.popleft()
        if steps >= 10:
            continue

        for src, tgt in rules:
            if not src:  # ignore empty source to avoid infinite loops
                continue
            start = 0
            while True:
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_str = current[:pos] + tgt + current[pos + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = pos + 1  # allow overlapping matches

    return "NO ANSWER!"
